namespace emon;


public static class Ocrinktest {
    internal static int OiLine(emon.Port.Cells lines, int page, int conf) {
        int t = Evidence.TlNew(lines, page, 1000, 2000, 5000, 2500, 1000, 2500, 5000, 2500, 0, 0, 0, 6);
        Evidence.TlSet(lines, t, Evidence.TlfConf(), conf);
        Evidence.TlSet(lines, t, Evidence.TlfInk(), 0);
        return t;
    }
    [Xunit.Fact]
    public static void TestUnreadInkKeepsSourcePageAndBoxWithoutInventedText() {
        emon.Port.Cells lines = emon.Port.NewCells();
        emon.Port.Cells inks = emon.Port.NewCells();
        emon.Port.Cells mask = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        OiLine(lines, 1, 800);
        Evidence.IkNew(inks, 1, 0);
        Evidence.IkSet(inks, 0, Evidence.IkfRole(), Evidence.IrBody());
        emon.Port.CellsPush(mask, 1);
        emon.Testport.AssertEq(Ocrledger.OcInkAccount(lines, inks, emon.Port.NewCells(), emon.Port.NewCells(), mask, ledger, emon.Port.NewCells(), emon.Port.NewCells()), 1, "source region has no recorded reading");
        emon.Testport.AssertEq(Model.LedgerCount(ledger), 1, "one region, not a guessed word count");
        emon.Testport.AssertEq(Model.LedgerReason(ledger, 0), Model.DrOcrUnreadInk(), "distinct from rejected OCR alternatives");
        emon.Testport.AssertEq(Model.LedgerPage(ledger, 0), 1, "source page owns the diagnostic");
        emon.Testport.AssertEq(Model.LedgerX0(ledger, 0), 1000, "source left");
        emon.Testport.AssertEq(Model.LedgerY0(ledger, 0), 2000, "source top");
        emon.Testport.AssertEq(Model.LedgerX1(ledger, 0), 5000, "source right");
        emon.Testport.AssertEq(Model.LedgerY1(ledger, 0), 2500, "source bottom");
        emon.Testport.AssertEq(Model.LedgerTextLen(ledger, 0), 0, "pixels supply no invented transcription");
        emon.Testport.AssertEq(Model.LedgerConf(ledger, 0), -1, "trace confidence is not a calibrated OCR word confidence");
    }
